def _simulate_mixture(self, op: ops.Operation, data: _StateAndBuffer,
            indices: List[int]) -> None:
        """Simulate an op that is a mixtures of unitaries."""
        if not isinstance(op, ops.Mixture):
            raise ValueError('_simulate_mixture should only be called on '
                             'mixtures.')

        # Simulate each of the unitaries.
        for op_i, op_i_weight in op.components.items():
            if op_i.is_parameterized():
                self._simulate_parameterized_op(op_i, data, indices)
            else:
                self._simulate_unitary(op_i, data, indices)

